import{_ as i,l as n,o as r,c as s,v as m,p,x as t,d as l,i as d,S as c,b as e}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"激活尺度漂移","description":"","frontmatter":{"title":"激活尺度漂移","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-scale-drift.md","filePath":"llm/activation-scale-drift.md","lastUpdated":1789023840000}'),h={name:"llm/activation-scale-drift.md"};function N(E,a,L,u,B,S){const o=n("Mermaid");return r(),s("div",null,[a[1]||(a[1]=m('<h1 id="激活尺度漂移" tabindex="-1">激活尺度漂移 <a class="header-anchor" href="#激活尺度漂移" aria-label="Permalink to &quot;激活尺度漂移&quot;">​</a></h1><div class="epigraph"><p>残差公路上的未归一化和可以随层、随时间变大；层归一化只钉进子层的那一截，并不自动钉住总线本身。</p><footer>—— 残差累加见 He et al., CVPR 2016；Transformer 中 LN 位置见 Xiong et al., 2020；对角增益见 Touvron et al., LayerScale, ICCV 2021</footer></div><p><a href="/llm/grad-norm-monitoring">上一课</a>监控的是反向。缺口是前向：<a href="/llm/residual-stream">残差流</a> 在 Pre-LN 下是 \\(x\\leftarrow x+F(\\mathrm{LN}(x))\\)，主干 \\(x\\) 不被 LN 重标。深度缩放只约束第 0 step 的 \\(\\mathrm{Var}(F)\\)；训练中 \\(F\\) 学会输出更大的增量，\\(\\|x\\|\\) 随层号与 step 涨。这会抬高注意力的 \\(q,k\\)（若无 QK-Norm）、抬高 FFN 中间激活、并在最后一层进入输出头前把动态范围交给一个 \\(\\gamma\\)。本课写激活传感器，以及 LayerScale / 最后一层 LN 作为结构阀，不重写 <a href="/llm/rmsnorm">RMSNorm</a> 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LN / RMSNorm 使 \\(F\\) 的输入 RMS 约为 1。\\(F\\) 仍可输出 RMS 为 10 的增量。加回主干后，下一层的 LN 再次把<strong>分支输入</strong>拉回，但主干范数已经变了。深度方向：底层 \\(\\|x\\|\\) 小、顶层大，形成「残差流放大」。时间方向：同一层的 \\(\\|x\\|\\) 随 CE 下降而涨。两者都让半精度与注意力 logits 承压，而梯度范数可以仍正常——因为 LN 的雅可比把 \\(F\\) 内部梯度按输入尺度除过了。</p><p>Post-LN 每层把加法后的 \\(x\\) 钉回，漂移改道到 LN 的内部统计与雅可比，Xiong 等人指出这使深层更难训。本课以当代默认 Pre-LN 为主，把 Post-LN 的「看起来没漂移」当成另一种病，留给下一课 warmup。</p><p><span class="marginnote">只打印 LN <strong>之后</strong>的激活，会得出「尺度很稳」的假象。传感器应打在残差加法之后、下一层 LN 之前，即总线本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对若干层记录：残差加法后的 RMS 中位数、FFN 中间激活的 max、以及最后一层进入 lm_head 前的 RMS。与注意力 row-max、LSE 同一 step 对齐。若顶层 RMS 相对底层持续指数涨，先检查是否忘了残差 dropout 的 inverted 缩放，再检查 \\(F\\) 输出投影是否被学习率放飞。</p><p>结构阀：</p><ul><li><strong>最终 LN。</strong> Pre-LN 解码器在栈顶再做一次归一化再进输出头，避免把总线范数直接乘进 \\(W_{\\mathrm{out}}\\)。这是惯例，不是可选项。</li><li><strong>LayerScale。</strong> \\(x\\leftarrow x+\\mathrm{diag}(\\alpha)F(\\cdot)\\)，\\(\\alpha\\) 起步接近 0 或很小，训练中学习每通道增益。Touvron 等人在深 ViT 上用它稳定深度方向的增量。</li><li><strong>QK-Norm / cap。</strong> 管的是注意力内部，不降低总线 RMS；总线仍要单独记。</li></ul><p>不要用「把全局梯度 clip 再紧一点」当激活漂移的对策：clip 不缩小 \\(x\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RMSNorm 的反向含 \\(1/\\mathrm{RMS}\\) 因子。主干 \\(x\\) 变大时，进 \\(F\\) 的分支仍被归一化，但 LN 相对 \\(x\\) 的梯度分配改变，\\(\\gamma\\) 承担更多「读写总线尺度」的工作。\\(\\gamma\\) 与嵌入、输出头一起放大，就是上一课 LSE 发散的一条路径。权重衰减若豁免 \\(\\gamma\\)（后课），这条路径更畅通。</p><p>LayerScale 把增量先缩小，类似深度缩放的可学习版，但发生在整个训练期而不只是初始化。它与 drop-path 可同时出现在视觉配方里；语言预训练更常只留最终 LN，把 \\(\\alpha\\) 固定为 1。加 LayerScale 等于加一组新参数，coord check 要包含 \\(\\alpha\\) 的幅度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把激活量化（INT8 校准）写完：那是压缩课。但训练期总线 RMS 的分位数，就是以后量化的范围估计。MoE 专家内部各有自己的激活尺度，全局一个数会骗人，应按专家桶打。下一课专门处理 Post-LN 仍被使用时，为何必须把 warmup 拉长——那是 LN 雅可比而不是总线 RMS 的故事。</p>',17)),(r(),p(c,null,{default:t(()=>[d(o,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%B8%BB%E5%B9%B2%20x%22%5D%20--%3E%20LN%5B%22LN%20%2F%20RMS%20%E5%8F%AA%E4%BD%9C%E7%94%A8%E5%9C%A8%E5%88%86%E6%94%AF%22%5D%0A%20%20LN%20--%3E%20F%5B%22F%20%E5%8F%AF%E8%BE%93%E5%87%BA%E5%A4%A7%E5%A2%9E%E9%87%8F%22%5D%0A%20%20F%20--%3E%20ADD%5B%22x%20%2B%20F%22%5D%0A%20%20ADD%20--%3E%20X2%5B%22%E6%80%BB%E7%BA%BF%20RMS%20%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20X2%20--%3E%20TOP%5B%22%E6%9C%80%E7%BB%88%20LN%20%E5%86%8D%E9%92%89%E8%BF%9B%E5%A4%B4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"Pre-LN 钉的是进 \\(F\\) 的分支，不钉残差总线；漂移应在加法之后测。"),e("li",null,"梯度范数正常不能排除激活放大。"),e("li",null,"最终 LN 是 Pre-LN 栈的必需阀；LayerScale 是可学习的增量缩放。"),e("li",null,"对策不是把 clip 拧紧。"),e("li",null,"出处：He et al., CVPR 2016；Xiong et al., 2020；Touvron et al., ICCV 2021。")],-1))])}const g=i(h,[["render",N]]);export{x as __pageData,g as default};
